 $('prompt').setAttribute('aria-describedby','parse-result');$('parse-result').setAttribute('aria-live','polite');$('prompt').addEventListener('input',clearPromptError);
 $('parse').onclick=()=>{const message=$('prompt').value.trim();if(!message||message.length>5000){$('error').classList.add('hidden');$('parse-result').textContent=!message?'Enter a booking or schedule-change request first, or choose an example above.':'Keep your request within 5,000 characters.';$('parse-result').classList.add('red');$('prompt').setAttribute('aria-invalid','true');$('prompt').focus();showError(Error($('parse-result').textContent));return}clearPromptError();const parseButton=$('parse');if(parseButton.disabled)return;parseButton.disabled=true;parseButton.textContent='Creating editable draft…';return task('Interpreting an untrusted request draft…',async()=>{const result=await api('assistant/parse',{message,outage:$('outage').checked});lastParseIntent=result.intent||null;conditionalDrafts=result.conditional_request||null;parseMissing=result.missing||[];clarificationSlots=result.clarification_slots||[];$('ai-firewall').classList.remove('hidden');$('ai-firewall').innerHTML='<p>Draft only: room, timing and role permissions are checked by the server when you check availability or submit.</p>'+(result.denied_claim?`<p class="red">Denied claim: ${E(result.denied_claim.category)}. ${E(result.denied_claim.reason)}</p>`+(result.denied_claim.allowed||[]).map(c=>`<button type="button" data-authorised-category="${E(c)}">Choose ${E(c)} category</button>`).join(''):'')+(parseMissing.length?clarificationSlots.map((a,i)=>`<button type="button" data-clarify-slot="${i}">${E(slot(a))} · ${E(a.name||a.room)}${a.capacity?' · '+E(a.capacity)+' seats':''} ↗</button>`).join(''):'');if(conditionalDrafts)$('ai-firewall').innerHTML+=`<p>Conditional request: choose a branch, review its fields and check availability. Neither branch is automatically booked.</p><details><summary>Review primary and fallback drafts</summary><pre>${E(JSON.stringify(conditionalDrafts,null,2))}</pre></details><button type="button" data-condition-branch="primary">Review primary draft</button><button type="button" data-condition-branch="fallback">Review fallback draft</button>`;if(result.source!=='unavailable')$('ai-firewall').innerHTML+=`<section class="assistant-draft-summary"><h3>${result.intent==='schedule_change'?'Schedule / leave draft':'Booking draft'} ready</h3><p>${result.intent==='schedule_change'?'Review the editable change fields. Leave requests are queued separately for independent review.':`${result.draft.day===undefined?'Day needs clarification':E(DAYS[result.draft.day])} · ${result.draft.start_period?'P'+E(result.draft.start_period):'Time needs clarification'} · ${E(result.draft.room||'Choose a room')} · ${E(result.draft.size||'Confirm')} attendees`}</p><button type="button" data-review-assistant="${result.intent}">Review editable fields ↓</button></section>`;$('confirm-clarification').classList.toggle('hidden',!parseMissing.length);$('parse-result').textContent=`${result.source} · ${parseMissing.length?'Needs clarification: '+parseMissing.join(', '):'Review all fields before submitting.'}`;if(result.intent==='schedule_change'){$('change-json').value=JSON.stringify(result.draft,null,2);showAssistantChange(result.draft);}else{$('booking-form').classList.remove('hidden');applyDraft(result.draft||{});}$('parse-result').scrollIntoView({block:'nearest',behavior:'smooth'});if(result.source!=='unavailable')toast('Editable draft created. Review the fields below.');else showError(Error('Assistant unavailable. Use the Manual Form.'));}).finally(()=>{parseButton.disabled=false;parseButton.textContent='Create editable draft';});};
 $('request-move').onclick=()=>{if(!$('own-session').value||$('move-day').value===''||$('move-period').value==='')return showError(Error('Select the session, new day and start period before previewing the change.'));const move={session:$('own-session').value,day:Number($('move-day').value),start_period:Number($('move-period').value)};if($('move-room').value)move.room=$('move-room').value;const current=rows().find(s=>s.id===move.session);if(current&&current.day===move.day&&current.start_period===move.start_period&&(!move.room||move.room===current.room))return showError(Error('This matches the current timetable. Choose a different day, period or room before submitting.'));return propose({moves:[move]});};$('request-leave').onclick=()=>{if(!$('leave-faculty').value||$('leave-day').value==='')return showError(Error('Select the faculty and leave day first.'));return queueLeave({faculty:$('leave-faculty').value,week:7,day:Number($('leave-day').value),start_period:1,duration:9});};$('submit-change').onclick=()=>{try{submitChangeDraft(JSON.parse($('change-json').value))}catch(e){showError(e)}};$('close-detail').onclick=()=>$('detail-dialog').close();
