async function queueLeave(window){await task('Submitting your leave request…',async()=>{await api('leaves',window);await refresh();tab='approvals';render();toast('Leave requested. An independent Admin must approve a valid timetable repair.');});}
function submitChangeDraft(change){const leave=change.faculty_leave||[];if(leave.length===1&&!['moves','room_closures','added_sessions'].some(k=>change[k]?.length))return queueLeave(leave[0]);return propose(change);}

let lastAssistantChange=null;
function showAssistantChange(change){lastAssistantChange=change;$('booking-form').classList.add('hidden');document.querySelector('.change-drawer').open=true;const move=change.moves?.[0],leave=change.faculty_leave?.[0];$('own-session').value=move?.session||'';$('move-day').value=move?.day??'';$('move-period').value=move?.start_period??'';$('move-room').value=move?.room||'';if(leave){$('leave-faculty').value=leave.faculty||'';$('leave-day').value=leave.day??'';}if(change.added_sessions?.length||change.room_closures?.length)$('advanced-change-draft').open=true;}
function openAssistantForMove(move){if(!state)return;document.querySelector('.workspace').classList.remove('copilot-collapsed');$('ai-mode').click();$('prompt').value=`Move ${move.session} to ${DAYS[move.day]} P${move.start_period}${move.room?' in '+move.room:''}`;$('parse').click();}

let sessionDraft=null;
function requestReauthentication(){if(!sessionDraft){const ids=['prompt','title','day','period','room','size','duration','category','room-type','own-session','move-day','move-period','move-room','leave-faculty','leave-day','change-json'];sessionDraft={owner:state?.user?.id,values:Object.fromEntries(ids.map(id=>[id,$(id).value])),accessible:$('accessible').checked,groups:[...$('mandatory-groups').selectedOptions].map(x=>x.value)};}$('username').value=state?.user?.id||'';$('password').value='';$('login-error').textContent='Your session expired. Sign in to continue without losing the draft.';if(!$('login-dialog').open)$('login-dialog').showModal();}
function restoreSessionDraft(){const draft=sessionDraft;sessionDraft=null;if(!draft||draft.owner!==state?.user?.id)return;for(const [id,value] of Object.entries(draft.values))$(id).value=value;$('accessible').checked=draft.accessible;for(const option of $('mandatory-groups').options)option.selected=draft.groups.includes(option.value);invalidate();}

async function readImportFile(file,kind){if(!file.name.toLowerCase().endsWith('.json'))throw Error('Unsupported file. Use a .json change file or ChronoGrid dataset; PDF, Excel and CSV cannot be imported directly.');if(file.size>5*1024*1024)throw Error('Import file is too large. Maximum size is 5 MB.');let data;try{data=JSON.parse(await file.text());}catch{throw Error('Invalid JSON in '+file.name+'. Fix the JSON syntax and import again. Your current timetable is unchanged.');}if(!data||typeof data!=='object'||Array.isArray(data))throw Error('The import must contain one JSON object.');if(kind==='change'){const allowed=['moves','faculty_leave','room_closures','added_sessions'];if(!Object.keys(data).length||Object.keys(data).some(k=>!allowed.includes(k)))throw Error('This is not a change file. Use moves, faculty_leave, room_closures or added_sessions. Full datasets belong in Rooms & resources → Import dataset; exported schedules are for validation, not direct replacement.');}else if(!['rooms','faculty','groups','courses','sessions','exams','bookings','priorities'].every(k=>Array.isArray(data[k])))throw Error('Not a complete ChronoGrid dataset. A timetable export or change file must not replace campus data.');return data;}
